import { Entity } from "./models/Entity.class";
import { GameComponent, ItemInterface } from "./models/Entity.interface";

export class Player extends Entity implements GameComponent {

    player_graphs: ItemInterface[] = [
        {
            level: 1,
            graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            exhaust_graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            graph: new Image(),
            exhaust_graph: new Image(),
            sound: new Audio()
        },
        {
            level: 2,
            graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            exhaust_graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            graph: new Image(),
            exhaust_graph: new Image(),
            sound: new Audio()
        },
        {
            level: 3,
            graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            exhaust_graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            graph: new Image(),
            exhaust_graph: new Image(),
            sound: new Audio()
        },
        {
            level: 4,
            graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            exhaust_graphs: [
                'data:image/png;base64,',
                'data:image/png;base64,'
            ],
            graph: new Image(),
            exhaust_graph: new Image(),
            sound: new Audio()
        }
    ]

    turnFullscreen = false;
    shooter=false;
    timer=0;
    player:ItemInterface;
    invulnerableTimer = 0;
    hitFlashTimer = 0;
    controlsEnabled: boolean = false;
    onHitFeedback?: (type: 'hull' | 'shield', damage: number, x: number, y: number) => void;

    isInvulnerable(): boolean {
        return this.invulnerableTimer > 0;
    }

    setInvulnerable(durationMs: number = 800) {
        this.invulnerableTimer = durationMs;
    }
    
    constructor(canvas: HTMLCanvasElement){
        super();

        let level = 0
        let subLevel=0
        this.scale=0.6;
        let img_src = this.player_graphs[level].graphs[subLevel];
        this.player_graphs[level].graph.src = img_src;

        let img_ex_src = this.player_graphs[level].exhaust_graphs[subLevel];
        this.player_graphs[level].exhaust_graph.src = img_ex_src;

        this.player = this.player_graphs[level];

        this.x = (canvas.width/2)-45;
        this.y = canvas.height+500;
        this.targeX_pos = (canvas.width/2)-45;
        this.targeY_pos = canvas.height-150;

        const setTargetFromPosition = (clientX: number, clientY: number, isTouch = false) => {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / (rect.width || 1);
            const scaleY = canvas.height / (rect.height || 1);
            const mouseX = (clientX - rect.left) * scaleX;
            const mouseY = (clientY - rect.top) * scaleY;
            const shipWidth = this.player?.graph?.width ? this.player.graph.width * this.scale : 60;
            const shipHeight = this.player?.graph?.height ? this.player.graph.height * this.scale : 45;

            // On touch, position ship 60px above finger so thumb does not occlude the ship
            const targetX = mouseX - shipWidth / 2;
            const targetY = isTouch ? (mouseY + 40 - shipHeight / 2) : (mouseY + 100 - shipHeight / 2);

            this.targeX_pos = Math.max(0, Math.min(canvas.width - shipWidth, targetX));
            this.targeY_pos = Math.max(100, Math.min(canvas.height + 100 - shipHeight, targetY));
        };

        const isPauseButtonArea = (clientX: number, clientY: number) => {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / (rect.width || 1);
            const scaleY = canvas.height / (rect.height || 1);
            const x = (clientX - rect.left) * scaleX;
            const y = (clientY - rect.top) * scaleY;
            return x >= canvas.width - 140 && y <= 65;
        };

        const isBombButtonArea = (clientX: number, clientY: number) => {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / (rect.width || 1);
            const scaleY = canvas.height / (rect.height || 1);
            const x = (clientX - rect.left) * scaleX;
            const y = (clientY - rect.top) * scaleY;
            const size = canvas.width < 600 ? 60 : 64;
            const pad = 15;
            return x <= 16 + size + pad && y >= canvas.height - size - 20 - pad;
        };

        const isActionArea = (clientX: number, clientY: number) => {
            return isPauseButtonArea(clientX, clientY) || isBombButtonArea(clientX, clientY);
        };

        // Mouse controls
        addEventListener('mousemove', (e: MouseEvent) => {
            if (!this.controlsEnabled) return;
            setTargetFromPosition(e.clientX, e.clientY, false);
        });

        addEventListener('mousedown', (e: MouseEvent) => {
            if (!this.controlsEnabled) return;
            if (e.button === 0) {
                if (!isActionArea(e.clientX, e.clientY)) {
                    this.shooter = true;
                    setTargetFromPosition(e.clientX, e.clientY, false);
                }
            }
        });

        addEventListener('mouseup', (e: MouseEvent) => {
            if (!this.controlsEnabled) return;
            if (e.button === 0) {
                this.shooter = false;
            }
        });

        // Keyboard controls
        addEventListener('keydown', (e: KeyboardEvent) => {
            if (!this.controlsEnabled) return;
            if (e.code === 'Space') {
                this.shooter = true;
            }
        });

        addEventListener('keyup', (e: KeyboardEvent) => {
            if (!this.controlsEnabled) return;
            if (e.code === 'Space') {
                this.shooter = false;
            }
        });

        // Mobile touch controls with passive: false and gesture prevention
        const handleTouchStart = (tm: TouchEvent) => {
            if (!this.controlsEnabled) return;
            if (tm.touches.length > 0) {
                const touch = tm.touches[0];
                if (isActionArea(touch.clientX, touch.clientY)) {
                    return;
                }
                if (tm.cancelable) tm.preventDefault();
                setTargetFromPosition(touch.clientX, touch.clientY, true);
                this.shooter = true;
            }
        };

        const handleTouchMove = (tm: TouchEvent) => {
            if (!this.controlsEnabled) return;
            if (tm.touches.length > 0) {
                const touch = tm.touches[0];
                if (isActionArea(touch.clientX, touch.clientY)) {
                    return;
                }
                if (tm.cancelable) tm.preventDefault();
                setTargetFromPosition(touch.clientX, touch.clientY, true);
            }
        };

        const handleTouchEnd = () => {
            if (!this.controlsEnabled) return;
            this.shooter = false;
        };

        canvas.addEventListener('touchstart', handleTouchStart, { passive: false });
        canvas.addEventListener('touchmove', handleTouchMove, { passive: false });
        canvas.addEventListener('touchend', handleTouchEnd, { passive: false });
        canvas.addEventListener('touchcancel', handleTouchEnd, { passive: false });

        // Global fallback listeners
        window.addEventListener('touchend', handleTouchEnd);
        window.addEventListener('touchcancel', handleTouchEnd);

    }
    
    draw(delta_time: number, ctx: CanvasRenderingContext2D, canvas: HTMLCanvasElement){
        this.x = this.lerp(this.x, this.targeX_pos, 0.15);
        this.y = this.lerp(this.y, this.targeY_pos, 0.15);

        // Blinking during invulnerability frames
        const isBlinking = this.invulnerableTimer > 0 && Math.floor(this.invulnerableTimer / 65) % 2 === 0;

        ctx.save();
        if (isBlinking) {
            ctx.globalAlpha = 0.28;
        }

        // Damage flash highlight
        if (this.hitFlashTimer > 0) {
            ctx.shadowColor = '#ff1744';
            ctx.shadowBlur = 24;
            if (ctx.filter) {
                ctx.filter = 'brightness(2.2) sepia(1) hue-rotate(-50deg) saturate(6)';
            }
        }

        ctx.drawImage(
            this.player.graph, 
            Math.floor(this.x),
            Math.floor(this.y)-100,
            this.player.graph.width*this.scale, 
            this.player.graph.height*this.scale
        );
        ctx.restore();

        ctx.save();
        if (isBlinking) {
            ctx.globalAlpha = 0.28;
        }
        this.draw_exhaust(ctx);
        ctx.restore();

        // - HEALTH BAR (HUD) -
        const isMobileScreen = canvas.width < 600;
        const barX = 12;
        const barY = 12;
        const barW = isMobileScreen ? Math.min(100, Math.max(70, Math.floor(canvas.width * 0.22))) : 140;
        const barH = isMobileScreen ? 11 : 14;
        const isHitBar = this.hitFlashTimer > 0;

        // Container background
        ctx.save();
        ctx.fillStyle = 'rgba(10, 16, 26, 0.75)';
        ctx.strokeStyle = isHitBar ? '#ff1744' : 'rgba(255, 255, 255, 0.4)';
        ctx.lineWidth = isHitBar ? 2 : 1;
        ctx.fillRect(barX, barY, barW, barH);
        ctx.strokeRect(barX, barY, barW, barH);

        // Health fill
        const currentHp = Math.max(0, Math.min(100, this.live));
        const fillW = (currentHp / 100) * (barW - 4);
        if (fillW > 0) {
            let fillColor = '#00e676';
            if (currentHp < 30) {
                fillColor = '#ff1744';
            } else if (currentHp < 60) {
                fillColor = '#ffab00';
            }
            if (isHitBar) {
                fillColor = '#ffffff';
            }
            ctx.fillStyle = fillColor;
            ctx.shadowColor = fillColor;
            ctx.shadowBlur = isHitBar ? 12 : 6;
            ctx.fillRect(barX + 2, barY + 2, fillW, barH - 4);
        }

        // Health Text
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = '#000000';
        ctx.shadowBlur = 4;
        ctx.font = isMobileScreen ? 'bold 9px Arial' : 'bold 10px Arial';
        ctx.textAlign = 'left';
        ctx.fillText(isMobileScreen ? `${Math.ceil(currentHp)}%` : `HP: ${Math.ceil(currentHp)}%`, barX + barW + 5, barY + barH - 2);
        ctx.restore();
    }

    draw_exhaust(ctx){
        ctx.drawImage(
            this.player.exhaust_graph, 
            Math.floor(this.x)+50,
            Math.floor(this.y)-60,
            this.player.exhaust_graph.width*this.scale, 
            this.player.exhaust_graph.height*this.scale
        );
        ctx.drawImage(
            this.player.exhaust_graph, 
            Math.floor(this.x),
            Math.floor(this.y)-60,
            this.player.exhaust_graph.width*this.scale, 
            this.player.exhaust_graph.height*this.scale
        );
    }

    update(delta_time: number, ctx: CanvasRenderingContext2D, canvas: HTMLCanvasElement){
        this.timer += delta_time;
        if(this.timer>300){
            this.timer=0;
        };
        if (this.invulnerableTimer > 0) {
            this.invulnerableTimer = Math.max(0, this.invulnerableTimer - delta_time);
        }
        if (this.hitFlashTimer > 0) {
            this.hitFlashTimer = Math.max(0, this.hitFlashTimer - delta_time);
        }
    }

    shoot(callback){
        if(this.shooter) {
            callback({
                x: this.x,
                y: this.y
            });
        }
    }

    distance(enemy: Entity): number{
        return this.getDistance(enemy);
    }

    destroy(callback){
        if(this.live <= 0) callback('player');
    }

    reduceLive(live: number){
        if (this.isInvulnerable()) {
            return;
        }
        this.live -= live;
        if (this.live < 0) this.live = 0;
        this.invulnerableTimer = 800;
        this.hitFlashTimer = 200;
        if (this.onHitFeedback) {
            this.onHitFeedback('hull', live, this.x, this.y);
        }
    }

    restoreLive(){
        this.live = 100;
    }

    getCenter(): { x: number; y: number } {
        const w = (this.player?.graph?.width || 60) * this.scale;
        const h = (this.player?.graph?.height || 45) * this.scale;
        return {
            x: this.x + w / 2,
            y: this.y - 100 + h / 2
        };
    }

    getCollisionRadius(): number {
        const w = (this.player?.graph?.width || 60) * this.scale;
        const h = (this.player?.graph?.height || 45) * this.scale;
        return Math.min(w, h) * 0.4;
    }

    getPosition(){
        return  {
            x:this.x,
            y:this.y
        }
    }

    fullScreen(){
        const element: any = document.getElementById('canvas');
    
        if(element.webkitRequestFullScreen){
            element.webkitRequestFullScreen();
            this.turnFullscreen=true;
            return;
        }
        element.mozRequestFullScreen();
        this.turnFullscreen=true;
        return;
      }    
}
